package com.takehome.savings.api.dto;

import java.util.UUID;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.takehome.savings.domain.SavingsAccount;

import io.swagger.v3.oas.annotations.media.Schema;

/**
 * Wire representation of a savings account - exactly the four fields of the
 * required account data model:
 * <ul>
 *   <li>{@code id} - autogenerated by the API. The VALUE is a random UUID (the
 *       sequential internal id never crosses the wire; see docs/DESIGN-TRADEOFFS.md D10).</li>
 *   <li>{@code accountNumber} - autogenerated by the API.</li>
 *   <li>{@code customerName} - mandatory input.</li>
 *   <li>{@code nickname} - optional input; serialised as field-absent when unset.</li>
 * </ul>
 * Audit columns (created/updated) stay server-side: the wire model does not
 * grow beyond the specified data model.
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
@Schema(description = """
        The account data model on the wire - exactly four fields; `nickname` is omitted from
        the JSON when absent. No audit columns.""")
public record AccountResponse(
        @Schema(description = """
                Autogenerated by the API. The value is an opaque UUIDv4 - 122 random bits, no
                derivation from anything sequential, nothing to brute force.""",
                format = "uuid", example = "0b9e6c2e-1111-4a2b-9c3d-5e6f70899a0b",
                requiredMode = Schema.RequiredMode.REQUIRED)
        UUID id,

        @Schema(description = "12 digits, last digit a Luhn check digit",
                example = "325748979052", requiredMode = Schema.RequiredMode.REQUIRED)
        String accountNumber,

        @Schema(description = "Customer the account belongs to, as canonicalised at creation",
                example = "Alice Tester", requiredMode = Schema.RequiredMode.REQUIRED)
        String customerName,

        @Schema(description = "Optional human label; absent when the account has none",
                example = "rainy day", minLength = 5, maxLength = 30)
        String nickname) {

    public static AccountResponse from(SavingsAccount account) {
        return new AccountResponse(
                account.getAccountUid(),
                account.getAccountNumber(),
                account.getCustomerName(),
                account.getNickname());
    }
}
